from collections import deque

# ACTIONS
TURN_LEFT = 0
TURN_RIGHT = 1
FORWARD = 2
PICKUP = 3
DROP = 4
TOGGLE = 5
DONE = 6

# object codes (from spec)
OBJ_UNSEEN = 0
OBJ_EMPTY = 1
OBJ_WALL = 2
OBJ_FLOOR = 3
OBJ_DOOR = 4
OBJ_KEY = 5
OBJ_BALL = 6
OBJ_BOX = 7
OBJ_GOAL = 8
OBJ_LAVA = 9
OBJ_AGENT = 10

PICKABLE = {OBJ_KEY, OBJ_BALL, OBJ_BOX}


def controller(obs, memory) -> int:
    """
    Improved reactive controller with stronger exploration heuristics and simple internal bookkeeping.

    Main changes in response to failure traces:
    - If the agent is not discovering new cells for several steps, force systematic scanning (alternate turns)
      and allow a limited number of forwards into unseen cells to escape local dead-ends.
    - Keep a short history of actual executed actions (from obs['last_action']) to detect stuck/repeat loops
      and change behavior if a repetitive pattern appears.
    - More conservative BFS/planning but fall back to aggressive exploration when no plan found.
    - Keep memory fields robustly initialized and avoid assuming previous outputs were executed (re-plan from obs).
    """

    image = obs['image']
    last_action = obs.get('last_action', None)

    # Initialize memory defaults
    if 'swap_xy' not in memory:
        # try to detect indexing: if image[3][6] looks valid (not unseen), assume image[col][row]
        try:
            maybe = image[3][6]
            memory['swap_xy'] = False if (isinstance(maybe, (list, tuple)) and maybe[0] != OBJ_UNSEEN) else True
        except Exception:
            memory['swap_xy'] = False
    if 'seen_max' not in memory:
        memory['seen_max'] = 0
    if 'steps_since_progress' not in memory:
        memory['steps_since_progress'] = 0
    if 'recent_executed' not in memory:
        memory['recent_executed'] = deque(maxlen=20)
    if 'allow_forward_unseen' not in memory:
        # how many consecutive allowed forwards into unseen we permit in current stagnation period
        memory['allow_forward_unseen'] = 0
    if 'last_plan_time' not in memory:
        memory['last_plan_time'] = 0
    if 'iter' not in memory:
        memory['iter'] = 0
    memory['iter'] += 1

    # record actual executed action if provided
    if last_action is not None:
        memory['recent_executed'].append(last_action)

    swap_xy = memory['swap_xy']

    def raw_cell(i, j):
        # i = column 0..6 (left->right), j = row 0..6 (far->near)
        try:
            if not swap_xy:
                return image[i][j]
            else:
                return image[j][i]
        except Exception:
            return (OBJ_UNSEEN, 0, 0)

    # count seen cells and update progress trackers
    seen_count = 0
    for i in range(7):
        for j in range(7):
            o, c, s = raw_cell(i, j)
            if o != OBJ_UNSEEN:
                seen_count += 1
    if seen_count > memory['seen_max']:
        memory['seen_max'] = seen_count
        memory['steps_since_progress'] = 0
        memory['allow_forward_unseen'] = 0  # reset allowance when new area seen
    else:
        memory['steps_since_progress'] += 1

    # Agent is always at (3,6) facing "up" in the image coordinates
    ax, ay = 3, 6

    def cell(x, y):
        if not (0 <= x <= 6 and 0 <= y <= 6):
            return (OBJ_UNSEEN, 0, 0)
        return raw_cell(x, y)

    def find_objs(obj_type):
        res = []
        for x in range(7):
            for y in range(7):
                o, col, st = cell(x, y)
                if o == obj_type:
                    res.append((x, y, col, st))
        return res

    def is_passable_obj(obj, state):
        return (obj in (OBJ_EMPTY, OBJ_FLOOR, OBJ_GOAL)) or (obj == OBJ_DOOR and state == 0)

    # BFS on visible passable cells to targets (set of (x,y))
    from collections import deque as _deque

    def bfs_to_targets(targets):
        start = (ax, ay)
        if start in targets:
            return [start]
        q = _deque([start])
        prev = {start: None}
        while q:
            x, y = q.popleft()
            for nx, ny in ((x, y - 1), (x - 1, y), (x + 1, y), (x, y + 1)):
                if not (0 <= nx <= 6 and 0 <= ny <= 6):
                    continue
                if (nx, ny) in prev:
                    continue
                o, col, st = cell(nx, ny)
                if o == OBJ_UNSEEN:
                    continue
                if not is_passable_obj(o, st):
                    continue
                prev[(nx, ny)] = (x, y)
                if (nx, ny) in targets:
                    path = [(nx, ny)]
                    cur = (x, y)
                    while cur is not None:
                        path.append(cur)
                        cur = prev[cur]
                    path.reverse()
                    return path
                q.append((nx, ny))
        return None

    def adjacent_positions(x, y):
        res = []
        for nx, ny in ((x, y - 1), (x - 1, y), (x + 1, y), (x, y + 1)):
            if 0 <= nx <= 6 and 0 <= ny <= 6 and (nx, ny) != (ax, ay):
                res.append((nx, ny))
        return res

    def targets_adjacent_to(x, y):
        res = []
        for (nx, ny) in adjacent_positions(x, y):
            o, col, st = cell(nx, ny)
            if o == OBJ_UNSEEN:
                continue
            if is_passable_obj(o, st):
                res.append((nx, ny))
        return res

    # produce low-level action to step from agent cell to a neighboring cell (image-local coordinates)
    def action_to_step(next_cell):
        nx, ny = next_cell
        dx = nx - ax
        dy = ny - ay
        # ahead
        if dx == 0 and dy == -1:
            front_o, _, _ = cell(ax, ay - 1)
            if front_o in PICKABLE:
                return PICKUP
            # allow forward into unseen if we are in a long stagnation (try to escape)
            if front_o == OBJ_UNSEEN:
                if memory['steps_since_progress'] >= 3 and memory['allow_forward_unseen'] < 2:
                    memory['allow_forward_unseen'] += 1
                    return FORWARD
                # otherwise try to rotate to reveal
                return TURN_RIGHT
            return FORWARD
        # left/right/back choices: prefer single rotations (we re-plan each call)
        if dx == -1 and dy == 0:
            return TURN_LEFT
        if dx == 1 and dy == 0:
            return TURN_RIGHT
        if dx == -1 and dy == -1:
            return TURN_LEFT
        if dx == 1 and dy == -1:
            return TURN_RIGHT
        if dx == 0 and dy == 1:
            return TURN_RIGHT
        if dx == -1 and dy == 1:
            return TURN_LEFT
        if dx == 1 and dy == 1:
            return TURN_RIGHT
        return TURN_RIGHT

    # examine front
    front_o, front_col, front_st = cell(ax, ay - 1)

    # 1) immediate goal in front -> forward
    if front_o == OBJ_GOAL:
        return FORWARD

    # 2) attempt to plan to visible goal
    goals = find_objs(OBJ_GOAL)
    if goals:
        targets = set((gx, gy) for (gx, gy, _, _) in goals)
        path = bfs_to_targets(targets)
        if path and len(path) >= 2:
            return action_to_step(path[1])
        # if unreachable due to doors, fall through to door/key handling

    # 3) handle door immediately in front
    if front_o == OBJ_DOOR:
        if front_st == 0:
            return FORWARD
        elif front_st == 1:
            # closed -> open
            # avoid toggling repeatedly: if we recently toggled and nothing changed, try rotating once first
            if len(memory['recent_executed']) >= 2 and memory['recent_executed'][-1] == TOGGLE and memory['recent_executed'][-2] == TOGGLE:
                # we've toggled twice recently, rotate to change viewpoint
                return TURN_LEFT
            return TOGGLE
        else:  # locked
            # if carrying matching key, toggle
            carried_o, carried_col, _ = cell(3, 6)
            if carried_o == OBJ_KEY and carried_col == front_col:
                return TOGGLE
            # else try to fetch matching key if visible
            keys = find_objs(OBJ_KEY)
            matching_keys = [(kx, ky, kc, ks) for (kx, ky, kc, ks) in keys if kc == front_col]
            if matching_keys:
                best_path = None
                for (kx, ky, kc, ks) in matching_keys:
                    adj_targets = targets_adjacent_to(kx, ky)
                    if not adj_targets:
                        continue
                    path = bfs_to_targets(set(adj_targets))
                    if path and (best_path is None or len(path) < len(best_path)):
                        best_path = path
                if best_path:
                    if len(best_path) >= 2:
                        return action_to_step(best_path[1])
                    # adjacent case: try pickup if in front else rotate
                    for (kx, ky, kc, ks) in matching_keys:
                        if (kx, ky) == (ax, ay - 1):
                            return PICKUP
                    return TURN_LEFT
            # no matching key visible -> rotate to search
            return TURN_RIGHT

    # 4) try to pick visible keys (general)
    keys_all = find_objs(OBJ_KEY)
    if keys_all:
        best_path = None
        best_key = None
        for (kx, ky, kc, ks) in keys_all:
            adj_targets = targets_adjacent_to(kx, ky)
            if not adj_targets:
                continue
            path = bfs_to_targets(set(adj_targets))
            if path and (best_path is None or len(path) < len(best_path)):
                best_path = path
                best_key = (kx, ky)
        if best_path:
            if len(best_path) >= 2:
                return action_to_step(best_path[1])
            else:
                kx, ky = best_key
                if (kx, ky) == (ax, ay - 1):
                    return PICKUP
                dx = kx - ax
                if dx < 0:
                    return TURN_LEFT
                else:
                    return TURN_RIGHT

    # 5) try to approach visible doors (prefer nearer/forward ones)
    doors = find_objs(OBJ_DOOR)
    if doors:
        # sort by nearer (larger y means closer to agent visually), prefer centered x
        doors_sorted = sorted(doors, key=lambda t: (-t[1], abs(t[0] - 3)))
        for (dx_d, dy_d, dcol, dst) in doors_sorted:
            # try to stand in the front cell (dx_d, dy_d+1) if passable and visible
            target = (dx_d, dy_d + 1)
            tx, ty = target
            if not (0 <= tx <= 6 and 0 <= ty <= 6):
                continue
            o, col, st = cell(tx, ty)
            if o == OBJ_UNSEEN:
                # if front of door is unseen, attempt to move forward into unseen a bit to discover
                # but only allow limited such attempts
                if memory['steps_since_progress'] >= 2 and memory['allow_forward_unseen'] < 2:
                    memory['allow_forward_unseen'] += 1
                    return FORWARD
                continue
            if not is_passable_obj(o, st):
                continue
            path = bfs_to_targets({target})
            if path:
                if len(path) >= 2:
                    return action_to_step(path[1])
                else:
                    # already at front cell; if door in front, next loop will handle it
                    return TURN_LEFT

    # 6) exploration fallback: if we are not discovering new cells, perform systematic scan
    # detect repetition: if recent executed actions look like a short repeated pattern, switch behavior
    if len(memory['recent_executed']) >= 8:
        # if dominated by rotations and forwards and no forwards succeeded (we can't easily detect success),
        # force a different rotation direction / attempt forward into unseen
        rot_count = sum(1 for a in memory['recent_executed'] if a in (TURN_LEFT, TURN_RIGHT))
        fwd_count = sum(1 for a in memory['recent_executed'] if a == FORWARD)
        if memory['steps_since_progress'] >= 3 and rot_count + fwd_count > 0:
            # try alternate turn direction or attempt forward into unseen
            # alternate between left and right based on iteration
            if (memory['iter'] % 2) == 0:
                if memory['allow_forward_unseen'] < 2:
                    memory['allow_forward_unseen'] += 1
                    return FORWARD
                return TURN_LEFT
            else:
                if memory['allow_forward_unseen'] < 2:
                    memory['allow_forward_unseen'] += 1
                    return FORWARD
                return TURN_RIGHT

    if memory['steps_since_progress'] >= 4:
        # force a scan: alternate turns to reveal unseen cells
        if (memory['steps_since_progress'] % 4) in (0, 1):
            return TURN_LEFT
        else:
            # occasionally try a forward into unseen to escape
            if memory['allow_forward_unseen'] < 2:
                memory['allow_forward_unseen'] += 1
                return FORWARD
            return TURN_RIGHT

    # 7) move to the most promising visible passable cell (prefer cells with small y -> forward)
    passable_cells = set()
    for x in range(7):
        for y in range(7):
            o, c, s = cell(x, y)
            if o != OBJ_UNSEEN and is_passable_obj(o, s):
                passable_cells.add((x, y))
    candidates = sorted(passable_cells, key=lambda t: (t[1], abs(t[0] - 3)))
    candidates = [c for c in candidates if c != (ax, ay)]
    for target in candidates:
        path = bfs_to_targets({target})
        if path and len(path) >= 2:
            return action_to_step(path[1])

    # 8) safe local actions:
    # if pickable in front -> pickup
    if front_o in PICKABLE:
        return PICKUP
    # if front visible and passable -> forward
    if front_o != OBJ_UNSEEN and is_passable_obj(front_o, front_st):
        return FORWARD
    # if front is a closed door -> try toggle
    if front_o == OBJ_DOOR:
        if front_st == 1:
            return TOGGLE
        elif front_st == 2:
            # locked: rotate to search key
            return TURN_RIGHT

    # 9) final fallback: rotate to explore
    # alternate left/right to avoid getting stuck turning same way
    if (memory['iter'] % 3) == 0:
        return TURN_LEFT
    else:
        return TURN_RIGHT
